    #[test]
    fn test_shift_and_select_ops() {
        // Tests shift operations, select, float↔int conversions
        let mlir = r#"
module {
  llvm.func @get_block_idx() -> i64
  llvm.func @shift_kernel(%arg0: !llvm.ptr<1>, %arg1: !llvm.ptr<1>) attributes {hacc.entry, hacc.function_kind = #hacc.function_kind<DEVICE>} {
    %c1 = llvm.mlir.constant(1 : i32) : i32
    %c2 = llvm.mlir.constant(2 : i32) : i32
    %shifted = arith.shli %c1, %c2 : i32
    %rshifted = arith.shrui %shifted, %c1 : i32
    %cond = arith.cmpi "sgt", %rshifted, %c1 : i32
    %selected = arith.select %cond, %rshifted, %c1 : i32
    %float_val = llvm.sitofp %selected : i32 to f32
    %int_val = llvm.fptosi %float_val : f32 to i32
    llvm.return
  }
}
"#;
        let cpp = convert_mlir_to_cpp(mlir, 256 * 1024)
            .expect("shift kernel conversion should succeed")
            .source;

        // Should generate shift operations
        assert!(
            cpp.contains("<<"),
            "Missing shift left operator in:\n{}",
            cpp
        );
        assert!(
            cpp.contains(">>"),
            "Missing shift right operator in:\n{}",
            cpp
        );
        // Should generate ternary for select
        assert!(
            cpp.contains("?") && cpp.contains(":"),
            "Missing ternary for select in:\n{}",
            cpp
        );
        // Should have C++ casts for float↔int
        assert!(
            cpp.contains("(float)") || cpp.contains("float)"),
            "Missing float cast in:\n{}",
            cpp
        );
        // Should NOT have any UNSUPPORTED comments
        assert!(
            !cpp.contains("UNSUPPORTED"),
            "Found UNSUPPORTED ops in:\n{}",
            cpp
        );
    }

