        let result = parse_insertvalue_operands(line);
        assert!(result.is_some());
        let (res, val, base, idx) = result.unwrap();
        assert_eq!(res, "%2");
        assert_eq!(val, "%0");
        assert_eq!(base, "%1");
        assert_eq!(idx, 0);

        let line2 = r#"    %4 = llvm.insertvalue %3, %2[1] : !llvm.struct<(i32, i1)>"#;
        let (res2, val2, base2, idx2) = parse_insertvalue_operands(line2).unwrap();
        assert_eq!(res2, "%4");
