    #[test]
    fn test_insertvalue_extractvalue_chain() {
        // Simulate the aggregate_fields tracking
        let mut aggregate_fields: HashMap<String, HashMap<usize, String>> = HashMap::new();
        let mut values: HashMap<String, CppValue> = HashMap::new();
        let mut next_var = 0usize;
        let mut code = String::new();

        // Simulate: %sum = some_add producing 42
        values.insert(
            "%sum".to_string(),
            CppValue {
                expr: "42".to_string(),
                cpp_type: "int32_t".to_string(),
            },
        );
        // Simulate: %flag = some_cmp producing false
        values.insert(
            "%flag".to_string(),
            CppValue {
                expr: "false".to_string(),
                cpp_type: "bool".to_string(),
            },
        );

        // insertvalue %sum, %undef[0] → %agg1
        let mut fields = HashMap::new();
        fields.insert(0, "%sum".to_string());
        aggregate_fields.insert("%agg1".to_string(), fields);
        values.insert(
            "%agg1".to_string(),
            CppValue {
                expr: "__v0".to_string(),
                cpp_type: "/* aggregate */".to_string(),
            },
        );

        // insertvalue %flag, %agg1[1] → %agg2
        let mut fields2 = aggregate_fields.get("%agg1").cloned().unwrap_or_default();
        fields2.insert(1, "%flag".to_string());
        aggregate_fields.insert("%agg2".to_string(), fields2);
        values.insert(
            "%agg2".to_string(),
            CppValue {
                expr: "__v1".to_string(),
                cpp_type: "/* aggregate */".to_string(),
            },
        );

        // extractvalue %agg2[0] should get %sum → "42"
        let ev_line = r#"    %result = llvm.extractvalue %agg2[0] : !llvm.struct<(i32, i1)>"#;
        emit_extractvalue(
            ev_line,
            "%result",
            &mut values,
            &mut next_var,
            &mut code,
            &aggregate_fields,
        );
        assert_eq!(values.get("%result").unwrap().expr, "__v0");
        assert!(code.contains("42"), "Expected 42 in code: {}", code);
        assert!(
            code.contains("int32_t"),
            "Expected int32_t in code: {}",
            code
        );

        // extractvalue %agg2[1] should get %flag → "false"
        let ev_line2 = r#"    %ovf = llvm.extractvalue %agg2[1] : !llvm.struct<(i32, i1)>"#;
        emit_extractvalue(
            ev_line2,
            "%ovf",
            &mut values,
            &mut next_var,
            &mut code,
            &aggregate_fields,
        );
        assert_eq!(values.get("%ovf").unwrap().expr, "__v1");
        assert!(code.contains("false"), "Expected false in code: {}", code);
        assert!(code.contains("bool"), "Expected bool in code: {}", code);
    }

